{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 3,
      "text_ar": "أدخلته إلى الجنة التي غرستها يمينك قبل أن تظهر الأرض.",
      "verse": 6
    },
    {
      "chapter": 3,
      "text_ar": "وأعطيته وصيتك الواحدة التي تعداها، وحالاً عينت له الموت ولنسله. ومنه وُلدت أمم وأسباط وشعوب وعشائر لا تحصى.",
      "verse": 7
    },
    {
      "chapter": 3,
      "text_ar": "وكل أمة سلكت حسب إرادتها، وصنعت أموراً شريرة أمام عينيك، وازددرت بوصاياك، ولم تمنعهم.",
      "verse": 8
    },
    {
      "chapter": 3,
      "text_ar": "ومع ذلك، مرة أخرى في مناسبة الزمن، جلبت الطوفان على السکّان في العالم وأهلكتهم.",
      "verse": 9
    },
    {
      "chapter": 3,
      "text_ar": "وقد حدث أن نفس الشيء حدث لهم. وكما جاء الموت لآدم، هكذا كان الطوفان لهؤلاء.",
      "verse": 10
    }
  ]
}
